const e="japon",l=1,s={habitants:"les Japonais",adjectif:"japonais",adjectifF:"japonaise",devise:"Travailler moins, sourire autant.",medaillon:"JP",chaineInfo:"JP NEWS 24",hymne:"Que l'archipel dure mille ans"},t={chambre:"Diète",chambreLong:"Diète nationale",chefGouvernement:"Premier ministre",chefEtat:"Empereur (rôle protocolaire)",passageForce:{label:"Question de confiance",description:"Le Premier ministre lie le sort du gouvernement à un texte : si la Diète refuse, il tombe ou dissout. En pratique, chacun vote oui après trois réunions de faction.",news:"Question de confiance sur {loi} : la Diète s'incline, la faction du fond note les noms"},censure:{label:"Motion de défiance",description:"La chambre basse peut renverser le gouvernement à la majorité. Le Premier ministre a alors dix jours pour dissoudre ou plier bagage.",news:"Motion de défiance déposée : les couloirs de la Diète retiennent leur thé"},dissolution:{label:"Dissolution de la Diète",description:"Le Premier ministre fait annoncer la dissolution de la chambre basse et appelle aux urnes, avec ou sans enthousiasme des factions.",news:"Dissolution de la Diète : les affiches de campagne arrivent avant l'annonce"}},n={type:"legislatives",label:"Élections générales",intro:"Haut-parleurs sur camionnettes, gants blancs et poignées de mains à la sortie du métro : la campagne japonaise est polie, minutée et très bruyante.",adversaires:[{id:"jp-adv-1",name:"Haruto Minagawa",parti:"Alliance du Progrès Citoyen",style:"chiffres",punchlines:["La dette, c'est comme un typhon : on sait quand elle arrive, jamais comment elle repart.","Mon programme tient en une page, le vôtre en un cartable.","Dix premiers ministres en dix ans : à ce rythme, on peut ouvrir un musée."],genre:"m"},{id:"jp-adv-2",name:"Sayuri Okabayashi",parti:"Front des Villages",style:"emotion",punchlines:["Dans mon village, il y a plus de grues sur les toits que d'enfants dans les écoles.","Je ne promets pas la lune, seulement une crèche à moins d'une heure de train.","On a demandé des berceaux, vous avez envoyé un rapport."],genre:"f"},{id:"jp-adv-3",name:"Daisuke Kurosawa-Tanabe",parti:"Mouvement du Dernier Métro",style:"attaque",punchlines:["Votre bilan, c'est le dernier métro : tout le monde y court, personne n'y arrive.","Vous avez des factions pour chaque saison.","Quand vous dites « examiner », le dossier prend sa retraite."],genre:"m"}],nuitElectorale:"Soirée électorale : les chaînes affichent des fleurs sur chaque siège gagné, et les perdants s'inclinent à quatre-vingt-dix degrés."},i=[{id:"japon-semaine-quatre-jours",title:"Semaine de quatre jours dans l'administration",domain:"travail",description:"Les ministères testent le vendredi libre. Les fonctionnaires apprennent avec stupeur que l'on peut rentrer avant que le dernier métro ne soit un souvenir.",accroche:"Le vendredi libéré, c'est un lundi de plus qu'on prépare avec soin.",effects:{popularite:4,cohesion:3,economie:-2,budget:-2},delayed:[{delay:3,effects:{economie:2,cohesion:2},label:"Productivité en hausse, sieste en baisse"}],groupStance:{"liberal-democrate-jp":.3,"democrate-constitutionnel":.7,restauration:-.2,"komei-paix":.5,"reiwa-citoyens":.8,"communistes-jp":.6},streetAnger:.1,setFlags:[]},{id:"japon-plafond-heures-sup",title:"Plafonnement strict des heures supplémentaires",domain:"travail",description:"Au-delà d'un certain seuil, les lumières des bureaux s'éteignent d'office. Des cadres se cachent dans les placards pour terminer leur dossier.",accroche:"Heures sup plafonnées : les salariés restent poliment pour ne pas déranger le plafond.",effects:{cohesion:4,popularite:3,economie:-3},delayed:[{delay:4,effects:{economie:3,pouvoirAchat:2},label:"Salariés reposés, résultats surprenants"}],groupStance:{"liberal-democrate-jp":-.3,"democrate-constitutionnel":.6,restauration:-.4,"komei-paix":.7,"reiwa-citoyens":.6,"communistes-jp":.9},streetAnger:.1,setFlags:["heures-sup-encadrees"]},{id:"japon-natalite-berceau",title:"Plan « Berceau de l'archipel »",domain:"sante",description:"Primes, crèches et congés parentaux pour relever une natalité qui bat chaque année de nouveaux records de discrétion.",accroche:"On offre un berceau, avec sa notice, son tampon et un cerisier en cadeau.",effects:{cohesion:3,popularite:3,budget:-7},delayed:[{delay:5,effects:{economie:4,cohesion:2},label:"Premières classes de maternelle à nouveau pleines"}],groupStance:{"liberal-democrate-jp":.5,"democrate-constitutionnel":.6,restauration:.4,"komei-paix":.8,"reiwa-citoyens":.5,"communistes-jp":.5},streetAnger:.1,setFlags:[]},{id:"japon-digues-anti-tsunami",title:"Programme de digues et de refuges anti-tsunami",domain:"ecologie",description:"Du béton, des escaliers vers les collines et des panneaux très polis disant « courez ». Les chantiers dureront autant que la mémoire du dernier séisme.",accroche:"Des digues très hautes, pour que la vague s'incline avec respect.",effects:{securite:5,economie:2,budget:-6,ecologie:-2},delayed:[{delay:4,effects:{cohesion:3,securite:2},label:"Littoral rassuré"}],groupStance:{"liberal-democrate-jp":.6,"democrate-constitutionnel":.4,restauration:.5,"komei-paix":.6,"reiwa-citoyens":.1,"communistes-jp":.2},streetAnger:.1,setFlags:[]},{id:"japon-normes-parasismiques",title:"Normes parasismiques renforcées pour tous les bâtiments",domain:"securite",description:"Chaque immeuble devra danser avec la terre plutôt que lui résister. Les promoteurs découvrent le mot « amortisseur ».",accroche:"Les immeubles danseront avec la terre, mais sans jamais lui marcher sur le pied.",effects:{securite:5,economie:-2,budget:-3},delayed:[{delay:3,effects:{securite:3,cohesion:2},label:"Villes plus souples"}],groupStance:{"liberal-democrate-jp":.2,"democrate-constitutionnel":.6,restauration:.1,"komei-paix":.7,"reiwa-citoyens":.4,"communistes-jp":.6},streetAnger:.2,setFlags:[]},{id:"japon-robots-soignants",title:"Déploiement de robots d'assistance aux aînés",domain:"sante",description:"Des machines souriantes servent le thé dans les maisons de retraite. Les aînés négocient aussitôt leur place aux échecs.",accroche:"Le robot soignant s'incline très bas, et l'aînée lui apprend à jouer au go.",effects:{economie:3,cohesion:2,budget:-4,popularite:1},delayed:[{delay:4,effects:{economie:3,international:2},label:"Exportation du modèle de robotique aimable"}],groupStance:{"liberal-democrate-jp":.7,"democrate-constitutionnel":.3,restauration:.4,"komei-paix":.5,"reiwa-citoyens":.8,"communistes-jp":-.2},streetAnger:.1,setFlags:[]},{id:"japon-teletravail-rural",title:"Télétravail et relocalisation hors de Tokyo",domain:"logement",description:"Des primes pour quitter la capitale et repeupler les villages. Les villages promettent de ne pas y ressembler trop vite.",accroche:"Travailler depuis la montagne : le réseau est bon, les grenouilles aussi.",effects:{cohesion:4,economie:1,budget:-4,ecologie:2},delayed:[{delay:4,effects:{cohesion:2,ecologie:2},label:"Écoles rurales sauvées de justesse"}],groupStance:{"liberal-democrate-jp":.2,"democrate-constitutionnel":.6,restauration:.5,"komei-paix":.6,"reiwa-citoyens":.7,"communistes-jp":.5},streetAnger:.1,setFlags:[]},{id:"japon-reforme-dette-publique",title:"Plan de maîtrise de la dette publique",domain:"institutions",description:"La dette atteint une taille que seuls des calculateurs poétiques peuvent écrire. Le plan promet de la regarder, enfin, en face.",accroche:"La dette est maîtrisée avec grâce, comme un bonsaï qu'on taille chaque année.",effects:{budget:8,popularite:-5,economie:-2,pouvoirAchat:-2},delayed:[{delay:4,effects:{budget:3,international:2},label:"Les agences de notation sourient presque"}],groupStance:{"liberal-democrate-jp":.4,"democrate-constitutionnel":-.4,restauration:.6,"komei-paix":.1,"reiwa-citoyens":.2,"communistes-jp":-.9},streetAnger:.5,setFlags:["austerite-douce"]},{id:"japon-hausse-taxe-consommation",title:"Hausse progressive de la taxe sur la consommation",domain:"institutions",description:"Un point de plus, annoncé avec des excuses en trois courbettes. Les caisses enregistrent, les clients comptent leurs pièces.",accroche:"La taxe monte d'un cran, le sourire du caissier ne baisse pas d'un millimètre.",effects:{budget:6,pouvoirAchat:-5,popularite:-5},delayed:[{delay:3,effects:{budget:3,economie:-1},label:"Rentrées fiscales plus fermes"}],groupStance:{"liberal-democrate-jp":.5,"democrate-constitutionnel":-.7,restauration:.3,"komei-paix":-.2,"reiwa-citoyens":-.4,"communistes-jp":-.9},streetAnger:.6,setFlags:[]},{id:"japon-renouvelables-offshore",title:"Parc éolien offshore et énergie des marées",domain:"energie",description:"Des éoliennes au large, des pêcheurs au milieu, et un comité de concertation pour dire à tout le monde qu'on les a écoutés.",accroche:"Le vent souffle sur la mer, la marée applaudit et l'éolienne fait la révérence.",effects:{ecologie:5,economie:2,budget:-5},delayed:[{delay:4,effects:{economie:3,international:2},label:"Indépendance énergétique en progrès"}],groupStance:{"liberal-democrate-jp":.3,"democrate-constitutionnel":.6,restauration:-.2,"komei-paix":.5,"reiwa-citoyens":.7,"communistes-jp":.3},streetAnger:.1,setFlags:["renouvelables-lancees"]},{id:"japon-fin-tampons-papier",title:"Dématérialisation des tampons administratifs",domain:"numerique",description:"Le fameux tampon sur papier disparaît des formulaires. Des fonctionnaires, émus, conservent le leur en souvenir.",accroche:"Le tampon de bois part à la retraite, entouré de ses douze encriers en larmes.",effects:{economie:3,popularite:2,cohesion:-2,budget:2},delayed:[{delay:3,effects:{economie:3,popularite:1},label:"Moins de files d'attente, plus de captures d'écran"}],groupStance:{"liberal-democrate-jp":.3,"democrate-constitutionnel":.4,restauration:-.4,"komei-paix":.2,"reiwa-citoyens":.8,"communistes-jp":.1},streetAnger:.1,setFlags:[]},{id:"japon-visa-travailleur-qualifie",title:"Statut de travailleur qualifié étranger",domain:"travail",description:"Des visas pour combler les postes que le vieillissement laisse vides. Le débat est vif, courtois et accompagné de nombreux thés.",accroche:"Bienvenue aux talents, la porte est ouverte et le formulaire reste, lui, très poli.",effects:{economie:4,cohesion:-3,popularite:-2},delayed:[{delay:4,effects:{economie:3,budget:2},label:"Chaînes de production moins dégarnies"}],groupStance:{"liberal-democrate-jp":.2,"democrate-constitutionnel":.5,restauration:-.7,"komei-paix":.4,"reiwa-citoyens":.6,"communistes-jp":.3},streetAnger:.3,setFlags:[]}],a=JSON.parse(`[{"id":"japon-seisme-majeur","title":"Le sol décide de s'exprimer","category":"climat","description":"Une secousse de grande ampleur fait vibrer les tasses, les gratte-ciel et l'agenda gouvernemental. Les trains s'arrêtent d'eux-mêmes avec une grâce toute nationale.","weight":6,"minTurn":2,"conditions":[],"choices":[{"id":"reconstruire","label":"Lancer la reconstruction immédiate","description":"Fonds d'urgence, ouvriers, chantiers sans délai.","effects":{"securite":3,"budget":-7,"cohesion":3,"popularite":3},"delayed":[{"delay":3,"effects":{"economie":3},"label":"Reprise des chantiers"}],"news":"Séisme : la reconstruction démarre avant même la fin des répliques"},{"id":"aide-locale","label":"Déléguer aux préfectures","description":"Laisser les autorités locales piloter les secours.","effects":{"budget":-3,"popularite":-2,"cohesion":1},"delayed":[],"news":"Séisme : les préfectures reçoivent les clés et les critiques"},{"id":"rapport","label":"Commander un rapport d'experts","description":"Étudier pendant que les gravats attendent.","effects":{"budget":-2,"popularite":-5,"securite":-3},"delayed":[{"delay":3,"effects":{"securite":3},"label":"Rapport publié, trois sismologues ravis"}],"news":"Séisme : un rapport de 900 pages annoncé pour l'an prochain"}],"kind":"evenement"},{"id":"japon-typhon-archipel","title":"Typhon sur l'archipel","category":"climat","description":"Un typhon fonce vers la côte pacifique, accompagné de bulletins météo de plus en plus graves et de supermarchés de plus en plus vides de nouilles.","weight":7,"minTurn":1,"conditions":[],"choices":[{"id":"evacuation","label":"Ordonner l'évacuation préventive","description":"Déplacer les populations avant l'arrivée du vent.","effects":{"securite":3,"popularite":2,"budget":-4,"economie":-2},"delayed":[],"news":"Typhon : évacuation exemplaire, quasi ponctuelle"},{"id":"fonds-catastrophe","label":"Débloquer le fonds de catastrophe","description":"Dédommager vite sinistrés et commerçants.","effects":{"budget":-6,"popularite":4,"cohesion":2},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Commerces rouverts"}],"news":"Typhon : le fonds de catastrophe se vide avec méthode"},{"id":"minimum","label":"Se limiter aux consignes de prudence","description":"Appeler chacun à rester chez soi.","effects":{"budget":1,"popularite":-5,"securite":-3},"delayed":[],"news":"Typhon : le gouvernement conseille de « fermer les volets »"}]},{"id":"japon-alerte-centrale-cotiere","title":"Alerte sur une centrale côtière","category":"securite","description":"Une centrale côtière tremble un peu plus que prévu. Les ingénieurs assurent que tout est sous contrôle, avec la voix de ceux qui n'ont pas dormi.","weight":4,"minTurn":3,"conditions":[{"gauge":"ecologie","op":"<","value":60}],"choices":[{"id":"arret","label":"Arrêter la centrale par précaution","description":"Mieux vaut perdre un peu de courant que la confiance.","effects":{"securite":4,"ecologie":2,"economie":-3,"budget":-3},"delayed":[],"news":"Centrale arrêtée : le pays baisse d'un degré le climatiseur"},{"id":"inspection","label":"Lancer une inspection indépendante","description":"Auditer en public, avec caméras et café.","effects":{"popularite":2,"cohesion":2,"budget":-2},"delayed":[],"news":"Inspection indépendante : les rapports sont enfin lisibles"},{"id":"minimiser","label":"Rassurer sans arrêter","description":"Maintenir l'activité en promettant la vigilance.","effects":{"economie":2,"popularite":-6,"securite":-4},"delayed":[],"news":"« Aucun risque », promet l'exécutif, devant des experts inquiets"}]},{"id":"japon-epuisement-au-travail","title":"Scandale d'épuisement au travail","category":"social","description":"Un grand groupe est accusé de journées interminables, avec bureaux éclairés et salariés endormis sur les claviers. L'opinion exige des comptes, et un jour de congé.","weight":6,"minTurn":2,"conditions":[{"gauge":"cohesion","op":"<","value":60}],"choices":[{"id":"inspection-travail","label":"Renforcer l'inspection du travail","description":"Plus d'agents, plus de contrôles, plus de tampons.","effects":{"cohesion":4,"popularite":3,"budget":-3,"economie":-2},"delayed":[],"news":"Inspection du travail : les bureaux éteignent la lumière à 19 h"},{"id":"charte","label":"Signer une charte avec les entreprises","description":"Des engagements volontaires, très solennels.","effects":{"popularite":1,"economie":1,"cohesion":-1},"delayed":[],"news":"Charte du bon horaire : mille signatures, aucune pénalité"},{"id":"ignorer","label":"Défendre la culture d'entreprise","description":"Souligner l'esprit de dévouement national.","effects":{"economie":2,"popularite":-6,"cohesion":-4},"delayed":[],"news":"Le gouvernement salue le dévouement, les syndicats l'épuisement"}]},{"id":"japon-factions-en-revolte","title":"Factions en révolte, la Diète gronde","category":"politique","description":"Une faction du parti dominant juge que le Premier ministre dure déjà trop. Les couloirs bruissent de la phrase magique : « Il faudrait un visage neuf ».","weight":5,"minTurn":3,"conditions":[{"gauge":"assemblee","op":"<","value":55}],"choices":[{"id":"remaniement","label":"Remanier en donnant des postes","description":"Un fauteuil par faction, la paix par rotation.","effects":{"assemblee":5,"popularite":-2,"budget":-1},"delayed":[],"news":"Remaniement : onze ministres changent de fauteuil, aucun de dossier"},{"id":"confiance-vote","label":"Poser la question de confiance","description":"Forcer chacun à se compter.","effects":{"assemblee":3,"popularite":-3,"cohesion":-2},"delayed":[],"news":"Question de confiance : tous votent oui, certains en grimaçant"},{"id":"dissolution-menace","label":"Menacer de dissoudre","description":"Rappeler aux factions que les sièges sont temporaires.","effects":{"assemblee":-2,"popularite":2,"international":-1},"delayed":[],"news":"Dissolution brandie : la Diète apprend soudain la loyauté"}]},{"id":"japon-village-sans-enfants","title":"Village sans enfants","category":"social","description":"Une école de village ferme faute d'élèves, la dernière en dix ans. Le conseil municipal organise une fête pour ses quatre habitants de moins de soixante ans.","weight":6,"minTurn":1,"conditions":[],"choices":[{"id":"fonds-villages","label":"Fonds de revitalisation rurale","description":"Aides à l'installation et à l'emploi local.","effects":{"cohesion":4,"budget":-4,"popularite":2},"delayed":[{"delay":4,"effects":{"cohesion":2},"label":"Quelques familles reviennent"}],"news":"Fonds ruraux : un village retrouve sa rentrée scolaire"},{"id":"regroupement","label":"Regrouper les communes","description":"Fusionner pour mutualiser mairies et pompiers.","effects":{"budget":3,"cohesion":-3,"popularite":-3},"delayed":[],"news":"Fusion des communes : trois mairies, un seul tampon"},{"id":"technologie","label":"Miser sur robots et télémédecine","description":"Un village connecté, avec un médecin à l'écran.","effects":{"economie":2,"budget":-3,"cohesion":1},"delayed":[],"news":"Villages connectés : le médecin consulte depuis une autre île"}]},{"id":"japon-retard-de-deux-minutes","title":"Retard de deux minutes, tout le pays s'excuse","category":"social","description":"Un train accuse deux minutes de retard. La compagnie présente trois excuses, le ministre une quatrième, et les passagers s'inquiètent surtout pour le conducteur.","weight":4,"minTurn":1,"conditions":[],"choices":[{"id":"enquete","label":"Ouvrir une enquête approfondie","description":"Comprendre la minute fautive.","effects":{"popularite":2,"budget":-1,"cohesion":1},"delayed":[],"news":"Retard de deux minutes : la commission siège enfin"},{"id":"modernise","label":"Investir dans la signalisation","description":"Moderniser les aiguillages, très lentement et très bien.","effects":{"economie":2,"budget":-4,"popularite":1},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Ponctualité record"}],"news":"Signalisation modernisée : le retard devient historique"},{"id":"tolerance","label":"Relativiser publiquement","description":"Rappeler que deux minutes, c'est déjà un exploit.","effects":{"popularite":-3,"cohesion":-1},"delayed":[],"news":"« Deux minutes, ce n'est pas un drame » : tollé dans le métro"}],"kind":"evenement"},{"id":"japon-navires-dans-le-detroit","title":"Navires dans le détroit voisin","category":"international","description":"Des navires étrangers patrouillent un peu trop près des îles du sud. Les diplomates échangent des notes d'une courtoisie glaciale.","weight":5,"minTurn":4,"conditions":[{"gauge":"international","op":"<","value":65}],"choices":[{"id":"diplomatie","label":"Privilégier le dialogue","description":"Rencontres, sommets, thé vert.","effects":{"international":3,"securite":-1,"budget":-1},"delayed":[],"news":"Détroit : la diplomatie ne dort plus"},{"id":"renfort","label":"Renforcer les garde-côtes","description":"Plus de navires, moins de surprises.","effects":{"securite":4,"budget":-5,"international":-2},"delayed":[],"news":"Garde-côtes renforcés : l'horizon est bien surveillé"},{"id":"alliance","label":"Solliciter les alliés","description":"Consolider les partenariats militaires et commerciaux.","effects":{"international":4,"securite":2,"popularite":-3},"delayed":[],"news":"Alliés sollicités : calendrier de réunions chargé"}]},{"id":"japon-canicule-ventilateurs","title":"Canicule et pénurie de ventilateurs","category":"climat","description":"Les thermomètres affolent les cartes météo. Les climatiseurs sont en rupture, les éventails reprennent du service, les bulletins demandent pardon.","weight":5,"minTurn":2,"conditions":[{"gauge":"ecologie","op":"<","value":60}],"choices":[{"id":"subvention-clim","label":"Subventionner les équipements","description":"Aider les ménages à se rafraîchir.","effects":{"pouvoirAchat":3,"popularite":3,"budget":-4,"ecologie":-3},"delayed":[],"news":"Subvention climatiseurs : la consommation électrique crie grâce"},{"id":"plan-chaleur","label":"Plan chaleur : salles fraîches publiques","description":"Ouvrir bibliothèques et gymnases au repos.","effects":{"cohesion":3,"budget":-2,"ecologie":1},"delayed":[],"news":"Salles fraîches : les bibliothèques font salle comble"},{"id":"conseils","label":"Diffuser des conseils","description":"Boire de l'eau, rester à l'ombre.","effects":{"popularite":-3,"securite":-2},"delayed":[],"news":"Conseils gouvernementaux : « penser à boire »"}]}]`),r=[{id:"japon-ponctualite",title:"Rétablir l'ordre des heures",brief:"Un trimestre où personne ne dort au bureau. Maintenez la cohésion à 66 : pas de vérification, mais beaucoup d'oreillers.",objective:{type:"gaugeAtLeast",gauge:"cohesion",value:66},reward:{cohesion:2,popularite:1},news:"Cohésion : les bureaux ferment, les cafés rouvrent"},{id:"japon-dette-sourire",title:"Faire sourire les agences de notation",brief:"Remonter le budget à 45. Les agences ne promettent rien, mais elles ont l'habitude de saluer avant de baisser la note.",objective:{type:"gaugeAtLeast",gauge:"budget",value:45},reward:{budget:2,international:1},news:"Budget : la dette passe de « vertigineuse » à « considérable »"},{id:"japon-loi-diete",title:"Faire voter un texte à la Diète",brief:"Un texte adopté ce trimestre, après sept consultations de faction et trois pauses thé.",objective:{type:"lawAdopted"},reward:{assemblee:2,popularite:1},news:"Diète : un texte adopté, la faction du fond reste dubitative"},{id:"japon-secousse",title:"Traverser une secousse avec élégance",brief:"Gérer correctement une crise, de préférence en gardant le sang-froid et la cravate droite.",objective:{type:"crisisWell"},reward:{popularite:2,securite:1},news:"Gestion de crise : un calme exemplaire, remarqué à l'étranger"},{id:"japon-club-de-presse",title:"Répondre au club de presse",brief:"Une conférence de presse ce trimestre. Les questions ont été transmises à l’avance ; les réponses, elles, restent à inventer.",objective:{type:"pressHeld"},reward:{popularite:2,cohesion:1},news:"Club de presse : le chef du gouvernement s’incline, puis répond presque",room:"presse",scene3d:"presse"}],o=JSON.parse('{"medias":["Le Courrier du Soleil Levant","Radio Cerisier 24","Le Journal du Dernier Métro","La Gazette du Thé Vert","Chaîne Archipel Direct"],"journalistes":[{"id":"japon-j-amamiya","name":"Keiko Amamiya","media":"Le Courrier du Soleil Levant","style":"incisive : pose sa question en s’inclinant, puis la repose en se redressant","genre":"f"},{"id":"japon-j-moriyama","name":"Takeshi Moriyama","media":"Le Journal du Dernier Métro","style":"tenace : suit le dirigeant jusqu’au quai du dernier métro","genre":"m"},{"id":"japon-j-shirasaki","name":"Yuna Shirasaki","media":"Radio Cerisier 24","style":"malicieuse : glisse le piège entre deux compliments sur la météo","genre":"f"},{"id":"japon-j-odagawa","name":"Kenji Odagawa","media":"La Gazette du Thé Vert","style":"méthodique : arrive avec trois classeurs et un thermos","genre":"m"},{"id":"japon-j-tsukimura","name":"Mariko Tsukimura","media":"Chaîne Archipel Direct","style":"enjouée : sourit tellement que la question ne fait presque pas mal","genre":"f"},{"id":"japon-j-nakashiro","name":"Hiroshi Nakashiro","media":"Le Courrier du Soleil Levant","style":"sceptique : note chaque « nous allons examiner » dans un carnet à part","genre":"m"},{"id":"japon-j-kitazono","name":"Aya Kitazono","media":"Radio Cerisier 24","style":"pointilleuse : vérifie vos chiffres pendant que vous les prononcez","genre":"f"},{"id":"japon-j-yamabuki","name":"Sōichi Yamabuki","media":"Le Journal du Dernier Métro","style":"nostalgique : compare tout à la grande époque des trains à vapeur"}],"questions":[{"id":"japon-q-dix-premiers-ministres","theme":"popularite","condition":{"gauge":"popularite","op":"<","value":40},"text":"Dix chefs de gouvernement en dix ans, et votre cote qui s’effrite : le pays commence à confondre le Kantei avec une porte tournante. Combien de temps comptez-vous tenir ?","answers":[{"tone":"franche","label":"Je ne promets pas la durée, seulement l’effort. Si les gens me retirent leur confiance, ils auront raison ; en attendant, je travaille.","effects":{"popularite":5,"assemblee":-2},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Les factions flairent la faiblesse"}],"news":"Le Premier ministre ne promet pas de durer, seulement de travailler"},{"tone":"langue-de-bois","label":"La stabilité n’est pas une affaire de calendrier mais de méthode. Ma méthode est stable, donc ma stabilité l’est aussi.","effects":{"popularite":2,"assemblee":-2},"news":"Le Premier ministre jure que sa méthode est stable"},{"tone":"offensive","label":"Dix prédécesseurs, et pas un n’a eu mon plan. Que les pessimistes réservent leur place au musée, nous construisons autre chose.","effects":{"popularite":4,"cohesion":-3,"assemblee":-2},"delayed":[{"delay":3,"effects":{"cohesion":-2},"label":"Les prédécesseurs se vexent poliment"}],"news":"Le Premier ministre renvoie les pessimistes au musée"}]},{"id":"japon-q-heures-sup-productivite","theme":"economie","condition":{"gauge":"economie","op":"<","value":45},"text":"Le dernier trimestre est faible et les bureaux restent éclairés jusqu’à minuit pour un résultat décevant. Travailler plus longtemps, est-ce vraiment travailler mieux ?","answers":[{"tone":"franche","label":"Non. Un salarié épuisé ne produit pas davantage, il produit des erreurs polies. Nous allons mesurer le résultat, plus l’heure de départ.","effects":{"cohesion":4,"economie":-3},"delayed":[{"delay":3,"effects":{"economie":3},"label":"Les équipes reposées rendent de meilleurs dossiers"}],"news":"Le Premier ministre : « Un salarié épuisé produit des erreurs polies »"},{"tone":"langue-de-bois","label":"La culture du travail est notre fierté et notre moteur. Nous allons concilier engagement exemplaire et équilibre de vie, dans un esprit d’harmonie.","effects":{"economie":2,"cohesion":-2},"news":"Travail : le Premier ministre prône « l’harmonie » entre bureau et foyer"},{"tone":"offensive","label":"Les chiffres ne sont mauvais que pour ceux qui rentrent à l’heure. Un pays se redresse avec des lumières allumées et des gens motivés.","effects":{"economie":5,"cohesion":-4,"popularite":-2},"news":"Le Premier ministre défend les lumières allumées après minuit"}]},{"id":"japon-q-dette-sourire","theme":"budget","condition":{"gauge":"budget","op":"<","value":40},"text":"La dette publique ressemble à une montagne que l’on regarde de loin, avec un grand sourire poli. Quand comptez-vous commencer l’ascension ?","answers":[{"tone":"franche","label":"Maintenant, et ce sera impopulaire. Hausses ciblées, économies réelles, et un tableau de bord public pour que chacun vérifie.","effects":{"budget":5,"popularite":-3},"delayed":[{"delay":2,"effects":{"pouvoirAchat":-2},"label":"Les ménages découvrent la facture à la caisse"}],"news":"Dette : le Premier ministre annonce l’ascension, sans le sourire"},{"tone":"langue-de-bois","label":"La soutenabilité de la dette est une priorité qui s’inscrit dans une trajectoire de consolidation progressive, étalée sur un horizon raisonnable.","effects":{"budget":2,"popularite":-2},"news":"Dette publique : « trajectoire de consolidation progressive »"},{"tone":"offensive","label":"Ceux qui s’inquiètent de la dette ont-ils vu la facture d’un typhon ? Je préfère investir dans les digues que dans les regrets comptables.","effects":{"popularite":4,"budget":-5,"international":-2},"news":"Le Premier ministre préfère les digues aux regrets comptables"}]},{"id":"japon-q-prix-riz-konbini","theme":"pouvoirAchat","condition":{"gauge":"pouvoirAchat","op":"<","value":45},"text":"Le prix du riz grimpe, la boîte-repas du konbini rétrécit, et le salarié moyen compte désormais les grains. Que répondez-vous à celui qui mange debout à midi ?","answers":[{"tone":"franche","label":"Que je le vois et que nous ne pourrons pas tout corriger. Aide ciblée pour les petits budgets, et enquête sur les marges des intermédiaires.","effects":{"pouvoirAchat":4,"budget":-3},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Les grossistes soupirent très poliment"}],"news":"Le Premier ministre promet une aide ciblée et une enquête sur les marges"},{"tone":"langue-de-bois","label":"Nous suivons l’évolution des prix avec une attention constante et une vigilance bienveillante, y compris à l’heure du déjeuner.","effects":{"pouvoirAchat":2,"popularite":-2},"news":"Prix du riz : « une vigilance bienveillante » au programme"},{"tone":"offensive","label":"On a vu pire : nos grands-parents mangeaient des patates douces en hiver. Un peu de sobriété n’a jamais empêché un pays de rayonner.","effects":{"budget":4,"popularite":-5,"cohesion":-2},"news":"Le Premier ministre vante la sobriété et les patates douces"}]},{"id":"japon-q-patrouilles-koban","theme":"securite","condition":{"gauge":"securite","op":"<","value":45},"text":"Les petits postes de police de quartier, les koban, manquent d’agents et les patrouilles s’espacent. Faudra-t-il un robot pour vous indiquer votre chemin et vous rassurer ?","answers":[{"tone":"franche","label":"Nous recruterons, et nous paierons mieux ceux qui gardent nos rues. Les robots viendront en renfort, jamais à la place du sourire d’un agent.","effects":{"securite":5,"budget":-3},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Les quartiers retrouvent leur agent de proximité"}],"news":"Koban : le Premier ministre veut des agents mieux payés, pas des robots"},{"tone":"langue-de-bois","label":"La proximité est au cœur de notre modèle de sécurité. Nous allons étudier les adaptations nécessaires avec toutes les parties prenantes.","effects":{"securite":2,"popularite":-2},"news":"Sécurité de proximité : le gouvernement « étudie les adaptations »"},{"tone":"offensive","label":"Un pays où l’on retrouve son portefeuille intact dans le métro n’a pas à trembler. Moins de tension, plus de confiance, et tout ira bien.","effects":{"popularite":3,"securite":-4,"assemblee":-2},"news":"Le Premier ministre : « Un portefeuille retrouvé vaut mille rapports »"}]},{"id":"japon-q-villages-videspour-jeunes","theme":"cohesion","condition":{"gauge":"cohesion","op":"<","value":45},"text":"Les jeunes partent vers la capitale, les villages s’endorment et les fêtes de quartier réunissent plus de grues en papier que d’enfants. Un pays peut-il vivre à deux vitesses ?","answers":[{"tone":"franche","label":"Non, et ce déséquilibre nous coûte déjà cher. Je propose crèches, trains rapides et bureaux décentralisés, mais cela se fera sur dix ans.","effects":{"cohesion":5,"budget":-3},"delayed":[{"delay":4,"effects":{"economie":2},"label":"Premiers bureaux régionaux ouverts, café compris"}],"news":"Le Premier ministre veut rééquilibrer l’archipel, sur dix ans"},{"tone":"langue-de-bois","label":"Chaque territoire a son génie propre, et nous sommes attachés à leur dynamisme dans une logique de valorisation partagée.","effects":{"cohesion":2,"popularite":-2},"news":"Territoires : « valorisation partagée » en vue"},{"tone":"offensive","label":"Ceux qui partent ont choisi la facilité des néons. La campagne a de l’air, du riz et du temps ; qu’ils reviennent avant que l’on ferme la gare !","effects":{"popularite":4,"cohesion":-4,"economie":-2},"news":"Le Premier ministre appelle les jeunes à quitter les néons"}]},{"id":"japon-q-centrales-et-eoliennes","theme":"ecologie","condition":{"gauge":"ecologie","op":"<","value":45},"text":"Entre les centrales côtières qui font trembler les riverains et les parcs éoliens qui dérangent les pêcheurs, existe-t-il une énergie qui ne dérange personne ?","answers":[{"tone":"franche","label":"Non. Toute énergie dérange quelqu’un ; la question est qui accepte quoi, contre quelle compensation. Je veux le débat avant le chantier.","effects":{"ecologie":4,"economie":-3},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Les riverains apprécient d’être écoutés avant de signer"}],"news":"Énergie : le Premier ministre exige le débat avant le chantier"},{"tone":"langue-de-bois","label":"Notre bouquet énergétique est équilibré, diversifié et résilient, dans le respect de toutes les sensibilités côtières et marines.","effects":{"ecologie":2,"economie":-2},"news":"Énergie : un bouquet « équilibré, diversifié et résilient »"},{"tone":"offensive","label":"Le vent souffle toute l’année et les pêcheurs ont assez de poissons. Nous installerons des éoliennes au large, avec ou sans cérémonie de coupe de ruban.","effects":{"ecologie":5,"cohesion":-3,"assemblee":-2},"delayed":[{"delay":2,"effects":{"pouvoirAchat":-2},"label":"Les pêcheurs bloquent le port en rangs très ordonnés"}],"news":"Le Premier ministre fonce sur l’éolien en mer"}]},{"id":"japon-q-detroit-voisin","theme":"international","condition":{"gauge":"international","op":"<","value":45},"text":"Vos voisins du détroit se plaignent de vos communiqués, vos alliés de votre prudence. Comment défendre l’archipel sans transformer chaque excuse en incident diplomatique ?","answers":[{"tone":"franche","label":"Par la fermeté tranquille : des positions claires, un dialogue ouvert et zéro provocation. La paix se travaille tous les jours, comme un jardin zen.","effects":{"international":5,"securite":-2},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Les faucons de la Diète trouvent cela bien discret"}],"news":"Détroit : le Premier ministre mise sur la « fermeté tranquille »"},{"tone":"langue-de-bois","label":"Nous poursuivons un dialogue constructif avec tous nos partenaires dans un esprit de coopération régionale et de stabilité durable.","effects":{"international":2,"popularite":-2},"news":"Diplomatie : le gouvernement poursuit un « dialogue constructif »"},{"tone":"offensive","label":"On ne négocie pas avec des navires en patrouille un dimanche. Nous renforcerons notre présence, et nos voisins sauront où nous sommes.","effects":{"securite":4,"popularite":2,"international":-5},"delayed":[{"delay":2,"effects":{"economie":-2},"label":"Les marchés détestent les communiqués trop sonores"}],"news":"Le Premier ministre renforce la présence maritime au sud"}]},{"id":"japon-q-factions-pcl","theme":"assemblee","condition":{"gauge":"assemblee","op":"<","value":45},"text":"Les factions de votre propre parti, le PCL, se disputent les postes avec la ferveur d’un tournoi de sumo. Êtes-vous encore le chef de la majorité ou seulement son arbitre ?","answers":[{"tone":"franche","label":"Arbitre quand il le faut, chef quand c’est nécessaire. Je confie les postes au mérite plutôt qu’à la faction, quitte à fâcher tout le monde.","effects":{"popularite":3,"assemblee":-3},"delayed":[{"delay":2,"effects":{"assemblee":-2},"label":"Les chefs de faction envoient des cartes de vœux glaciales"}],"news":"Le Premier ministre veut des postes au mérite, pas aux factions"},{"tone":"langue-de-bois","label":"Notre parti est une famille aux sensibilités plurielles, et c’est sa richesse. Le dialogue interne reste constant, respectueux et confidentiel.","effects":{"assemblee":2,"popularite":-2},"news":"Majorité : le PCL est « une famille aux sensibilités plurielles »"},{"tone":"offensive","label":"Les factions peuvent crier, la Diète décide. Qui veut un portefeuille signe le programme ; les autres peuvent prendre le thé dans le couloir.","effects":{"assemblee":4,"popularite":2,"cohesion":-4},"delayed":[{"delay":3,"effects":{"assemblee":-3},"label":"Une faction menace de voter contre le prochain budget"}],"news":"Le Premier ministre aux factions : « Signez le programme ou buvez du thé »"}]},{"id":"japon-q-majorite-confortable","theme":"assemblee","condition":{"gauge":"assemblee","op":">","value":70},"text":"Votre majorité à la Diète est si confortable que l’opposition vote déjà des motions en bâillant. Ne craignez-vous pas de gouverner sans contradicteur, donc sans réflexe ?","answers":[{"tone":"franche","label":"Si, c’est un risque. J’inviterai moi-même l’opposition à vérifier mes textes, parce qu’un pouvoir sans contradiction finit par s’endormir.","effects":{"assemblee":-3,"popularite":4,"international":2},"delayed":[{"delay":2,"effects":{"cohesion":2},"label":"Les débats à la Diète retrouvent un peu de relief"}],"news":"Le Premier ministre invite l’opposition à corriger ses textes"},{"tone":"langue-de-bois","label":"Une majorité solide permet un travail serein et des réformes inscrites dans la durée, sans jamais négliger l’écoute des voix minoritaires.","effects":{"assemblee":2,"popularite":-2},"news":"Majorité : « un travail serein » à la Diète"},{"tone":"offensive","label":"Gouverner sans obstacle, c’est le rêve de tout navigateur. L’opposition aura la parole quand elle aura des idées aussi nettes que mes agendas.","effects":{"assemblee":4,"popularite":3,"cohesion":-4,"international":-2},"news":"Le Premier ministre ironise sur les « idées » de l’opposition"}]},{"id":"japon-q-robots-aines","theme":"economie","condition":{"gauge":"economie","op":">","value":65},"text":"Votre pays vieillit vite, vos robots d’assistance aux aînés sont prêts et la croissance est bonne. Un jour, la machine servira-t-elle le thé à nos grands-parents à votre place ?","answers":[{"tone":"franche","label":"Elle aidera, mais le thé de grand-mère restera humain. Je veux des robots qui libèrent du temps de présence, pas des robots qui l’économisent.","effects":{"economie":3,"budget":-3,"cohesion":2},"delayed":[{"delay":3,"effects":{"economie":2},"label":"Les premiers robots soignants font l’unanimité des petits-enfants"}],"news":"Le Premier ministre veut des robots qui libèrent du temps humain"},{"tone":"langue-de-bois","label":"L’innovation au service de la dignité du grand âge est un axe majeur de notre stratégie de croissance inclusive et durable.","effects":{"economie":2,"cohesion":-2},"news":"Robotique : innovation, dignité et croissance au programme"},{"tone":"offensive","label":"La robotique est notre atout, et nous allons l’exporter à ceux qui en rêvent. Que les sceptiques continuent d’éplucher leurs légumes à la main.","effects":{"economie":5,"international":3,"cohesion":-4},"news":"Le Premier ministre veut exporter ses robots soignants"}]},{"id":"japon-q-trop-populaire","theme":"popularite","condition":{"gauge":"popularite","op":">","value":65},"text":"Votre cote est excellente, au point que certains y voient un bug du sondage. Quel secret cache un chef de gouvernement qui dure plus de deux saisons ?","answers":[{"tone":"franche","label":"Aucun, sinon le sommeil perdu. La popularité est un prêt, pas un cadeau, et le remboursement arrive toujours au plus mauvais moment.","effects":{"cohesion":3,"popularite":-3},"delayed":[{"delay":2,"effects":{"assemblee":2},"label":"Les alliés apprécient cette modestie inhabituelle"}],"news":"Le Premier ministre : « La popularité est un prêt, pas un cadeau »"},{"tone":"langue-de-bois","label":"Le secret, c’est l’écoute, la constance et un grand respect de chacun. Les sondages passent, les principes restent, et le thé refroidit.","effects":{"popularite":2,"international":-2},"news":"Le Premier ministre explique son succès par « l’écoute et la constance »"},{"tone":"offensive","label":"Le secret ? Un bilan. Que mes rivaux me demandent leurs cours particuliers ; la première leçon est gratuite, la suivante est de la modestie.","effects":{"popularite":4,"assemblee":-4,"cohesion":-2},"news":"Le Premier ministre propose des cours particuliers à ses rivaux"}]},{"id":"japon-q-tampons-hanko","theme":"budget","condition":{"gauge":"budget","op":">","value":60},"text":"Un document officiel exige encore sept tampons, dont trois pour confirmer que les quatre premiers sont valides. Quel est le coût de cette gestion à l’encre rouge ?","answers":[{"tone":"franche","label":"Des milliards d’heures par an. Nous passons au numérique, et les fonctionnaires attachés au tampon garderont leur coussin d’encre en souvenir.","effects":{"budget":4,"cohesion":-2},"delayed":[{"delay":3,"effects":{"economie":3},"label":"Les dossiers se traitent désormais en minutes, avec moins de rouge"}],"news":"Le Premier ministre dit adieu aux sept tampons"},{"tone":"langue-de-bois","label":"La simplification administrative est un chantier transversal, mené avec méthode, en concertation avec les agents et dans le respect de nos traditions.","effects":{"budget":2,"popularite":-2},"news":"Simplification : un chantier « transversal et respectueux »"},{"tone":"offensive","label":"Je signerai moi-même la suppression de chaque tampon superflu. Un pays qui voyage à la vitesse du shinkansen ne peut pas tamponner à la vitesse d’un escargot.","effects":{"economie":4,"assemblee":-3,"budget":3,"cohesion":-2},"news":"Le Premier ministre signe la mort du tampon"}]},{"id":"japon-q-exercices-evacuation","theme":"securite","condition":{"gauge":"securite","op":">","value":70},"text":"Chaque année, des millions de personnes s’entraînent à s’abriter sous une table à l’heure dite. Quand le vrai séisme viendra, serons-nous prêts ou seulement très bien entraînés à faire semblant ?","answers":[{"tone":"franche","label":"Nous serons prêts à 80 %, ce qui est excellent mais insuffisant. Je veux des exercices surprises, des bâtiments contrôlés et des refuges rénovés.","effects":{"securite":4,"popularite":-3},"delayed":[{"delay":3,"effects":{"cohesion":2},"label":"Les voisins apprennent enfin le nom de leur refuge"}],"news":"Séisme : le Premier ministre veut des exercices surprises"},{"tone":"langue-de-bois","label":"La culture de la prévention est profondément ancrée dans notre société, et nous la renforçons dans un esprit de vigilance partagée.","effects":{"securite":2,"budget":-2},"news":"Prévention : le gouvernement parle de « vigilance partagée »"},{"tone":"offensive","label":"Il suffit de regarder les autres nations pour voir que nous sommes les meilleurs. Nous exporterons notre expertise, et personne ne prendra plus de leçons.","effects":{"international":4,"securite":3,"cohesion":-3,"budget":-2},"news":"Le Premier ministre veut exporter l’expertise parasismique"}]},{"id":"japon-q-floraison-cerisiers","theme":"ecologie","text":"Les cerisiers fleurissent de plus en plus tôt et le pique-nique sous les fleurs commence en plein hiver. Le climat a-t-il bousculé le calendrier du printemps ?","answers":[{"tone":"franche","label":"Oui, et ce n’est pas seulement poétique. Nous devons réduire nos émissions, même si cela fâche des industriels très ponctuels.","effects":{"ecologie":5,"economie":-3},"delayed":[{"delay":3,"effects":{"international":2},"label":"Les partenaires saluent le nouveau cap climatique"}],"news":"Le Premier ministre admet que le printemps arrive trop tôt"},{"tone":"langue-de-bois","label":"La nature nous rappelle sans cesse notre responsabilité, et nous avançons avec détermination vers un avenir plus durable et plus floral.","effects":{"ecologie":2,"popularite":-2},"news":"Climat : le gouvernement avance vers un avenir « plus floral »"},{"tone":"offensive","label":"Les cerisiers s’adapteront, comme nous. Je ne sacrifierai pas une usine pour avancer un pique-nique d’une semaine.","effects":{"economie":4,"ecologie":-4,"popularite":2},"news":"Le Premier ministre refuse de sacrifier une usine aux cerisiers"}]},{"id":"japon-q-crise-seisme","theme":"crise","crisisId":"japon-seisme-majeur","text":"Le sol vient de trembler fort, les tasses ont valsé et les lignes de métro sont à l’arrêt. Premier ministre, que dites-vous aux habitants qui attendent des nouvelles sous les tables ?","answers":[{"tone":"franche","label":"Que nous mesurons les dégâts, que les secours sont engagés et que je ne dormirai pas avant d’avoir des informations fiables pour tous.","effects":{"popularite":4,"budget":-3},"delayed":[{"delay":2,"effects":{"cohesion":3},"label":"Les voisins s’organisent et partagent leurs bouteilles d’eau"}],"news":"Séisme : le Premier ministre veille et promet des informations fiables"},{"tone":"langue-de-bois","label":"Nos pensées vont aux habitants touchés. Les dispositifs prévus sont activés dans le plus grand calme et dans un esprit de responsabilité collective.","effects":{"cohesion":2,"popularite":-2},"news":"Séisme : les dispositifs d’urgence sont « activés dans le calme »"},{"tone":"offensive","label":"Nos bâtiments tiennent mieux que partout ailleurs, et ceux qui crient à la catastrophe sont les mêmes qui critiquaient nos normes. Je ne laisserai personne polémiquer.","effects":{"securite":3,"popularite":3,"cohesion":-4},"news":"Le Premier ministre ferme la porte aux polémiques sur les normes"}]},{"id":"japon-q-crise-typhon","theme":"crise","crisisId":"japon-typhon-archipel","text":"Le typhon arrive par la côte pacifique, les trains sont suspendus et les employés se demandent s’ils doivent aller au bureau pour montrer qu’ils sont sérieux. Que leur conseillez-vous ?","answers":[{"tone":"franche","label":"Restez chez vous. Aucun dossier ne vaut un toit sur la tête, et aucun employeur ne doit vous reprocher d’avoir préféré rester en vie.","effects":{"securite":4,"economie":-3},"delayed":[{"delay":1,"effects":{"popularite":2},"label":"Les salariés lui envoient des remerciements tamponnés trois fois"}],"news":"Typhon : le Premier ministre dit aux salariés de rester chez eux"},{"tone":"langue-de-bois","label":"Chacun est invité à suivre les consignes des autorités locales et à faire preuve de bon sens, dans le respect des règles de sécurité en vigueur.","effects":{"securite":2,"popularite":-2},"news":"Typhon : le gouvernement invite à « faire preuve de bon sens »"},{"tone":"offensive","label":"Nous traverserons ce typhon comme les précédents : debout, coiffés et à l’heure. Je serai à mon poste, et je n’attends pas moins des autres.","effects":{"popularite":3,"securite":-4,"cohesion":-2},"delayed":[{"delay":2,"effects":{"popularite":-2},"label":"Des photos de salariés trempés font le tour des réseaux"}],"news":"Typhon : le Premier ministre sera à son poste, coiffé et à l’heure"}]},{"id":"japon-q-crise-centrale","theme":"crise","crisisId":"japon-alerte-centrale-cotiere","text":"La centrale côtière a eu une alerte, les ingénieurs affirment que tout est sous contrôle et les riverains regardent la mer d’un air peu convaincu. Comment rétablir la confiance ?","answers":[{"tone":"franche","label":"En publiant chaque mesure en temps réel et en suspendant la centrale tant que les inspecteurs indépendants n’ont pas tout vérifié.","effects":{"cohesion":4,"securite":3,"economie":-4},"delayed":[{"delay":3,"effects":{"international":2},"label":"Les partenaires saluent la transparence de l’archipel"}],"news":"Centrale : le Premier ministre suspend et publie les mesures en direct"},{"tone":"langue-de-bois","label":"La sûreté est notre priorité absolue. Les procédures ont été respectées et les analyses se poursuivent avec l’autorité de contrôle concernée.","effects":{"securite":2,"cohesion":-2},"news":"Centrale : « la sûreté est la priorité absolue », répète le gouvernement"},{"tone":"offensive","label":"Je ne laisserai pas une alerte transformer le pays en panique. Notre industrie est exemplaire, et ceux qui jouent avec les peurs devront en répondre.","effects":{"economie":4,"ecologie":-3,"cohesion":-4},"delayed":[{"delay":2,"effects":{"popularite":-3},"label":"Un sondage montre des riverains toujours plus inquiets"}],"news":"Centrale : le Premier ministre accuse ceux qui jouent avec les peurs"}]},{"id":"japon-q-crise-retard-deux-minutes","theme":"crise","crisisId":"japon-retard-de-deux-minutes","text":"Un train a accusé deux minutes de retard et le pays tout entier s’excuse, du chef de gare au ministre. Ne trouvez-vous pas que nous avons un léger problème de proportions ?","answers":[{"tone":"franche","label":"Si, et je vais être le premier à demander moins d’excuses et plus de réparations. Un train à l’heure vaut mieux qu’un sourire désolé.","effects":{"popularite":3,"cohesion":-2},"delayed":[{"delay":2,"effects":{"economie":2},"label":"Les compagnies investissent dans les aiguillages plutôt que dans les courbettes"}],"news":"Retard de deux minutes : le Premier ministre veut moins d’excuses"},{"tone":"langue-de-bois","label":"La ponctualité fait partie de notre identité collective et de notre exigence de service. Nous restons attentifs à ces enjeux de qualité.","effects":{"cohesion":2,"popularite":-2},"news":"Ponctualité : le gouvernement reste « attentif aux enjeux de qualité »"},{"tone":"offensive","label":"Deux minutes, c’est déjà trop ! Je demande un audit, trois excuses publiques et un chronomètre accroché à chaque quai.","effects":{"securite":3,"budget":-3,"popularite":-2,"economie":-2},"news":"Le Premier ministre exige un chronomètre sur chaque quai"}]},{"id":"japon-q-crise-navires-detroit","theme":"crise","crisisId":"japon-navires-dans-le-detroit","text":"Des navires étrangers patrouillent un peu trop près des îles du sud, et vos diplomates multiplient les notes polies. Quelle est votre ligne : l’indignation ou le thé avec le voisin ?","answers":[{"tone":"franche","label":"Le dialogue, d’abord et toujours, mais avec des garde-côtes visibles en mer. On discute mieux quand on est sûr que personne ne passera.","effects":{"international":4,"budget":-3},"delayed":[{"delay":2,"effects":{"securite":2},"label":"Les marins apprécient de voir enfin les gyrophares"}],"news":"Îles du sud : le Premier ministre associe dialogue et garde-côtes"},{"tone":"langue-de-bois","label":"Nous suivons la situation de près avec nos partenaires et réaffirmons notre attachement au droit international et au règlement pacifique des différends.","effects":{"international":2,"securite":-2},"news":"Îles du sud : attachement réaffirmé au « règlement pacifique »"},{"tone":"offensive","label":"Nos îles sont nos îles, et je le dirai à chaque tribune. Ceux qui testent notre patience découvriront que nous en avons beaucoup, mais pas infiniment.","effects":{"securite":4,"popularite":3,"international":-5},"delayed":[{"delay":3,"effects":{"economie":-3},"label":"Les marchés prennent peur et les cours oscillent"}],"news":"Îles du sud : « Notre patience est grande, pas infinie »"}]},{"id":"japon-q-crise-dissolution-rumeur","theme":"crise","text":"On murmure dans les couloirs de la Diète que vous préparez une dissolution surprise pour profiter d’un sondage favorable. Les affiches seraient-elles déjà imprimées ?","answers":[{"tone":"franche","label":"Je ne dissoudrai que si le pays l’exige, pas si un sondage me flatte. Et je réponds à ceux qui croient aux affiches : elles ne sont pas imprimées.","effects":{"assemblee":3,"popularite":-2},"delayed":[{"delay":2,"effects":{"popularite":2},"label":"Les électeurs saluent la franchise, malgré tout"}],"news":"Le Premier ministre dément toute dissolution de circonstance"},{"tone":"langue-de-bois","label":"Je ne commente ni les rumeurs ni les calendriers. Le gouvernement travaille et la Diète siège ; le reste appartient aux conditions de l’avenir.","effects":{"assemblee":2,"popularite":-2},"news":"Dissolution : le Premier ministre ne commente « ni rumeurs ni calendriers »"},{"tone":"offensive","label":"Si l’opposition a peur des urnes, c’est qu’elle sait comment elles votent. Qu’elle prépare ses affiches : les miennes sont imprimées en trois couleurs.","effects":{"popularite":4,"assemblee":-3,"cohesion":-3},"delayed":[{"delay":3,"effects":{"assemblee":-2},"label":"L’opposition dépose une motion pour le principe"}],"news":"Le Premier ministre aux adversaires : « Mes affiches sont imprimées »"}]},{"id":"japon-q-scandale-banquet","theme":"scandale","text":"Un banquet de factions dans un restaurant discret aurait été facturé à un ministère sous la rubrique « réunion de travail et sushi ». Votre conscience digère-t-elle bien ?","answers":[{"tone":"franche","label":"Mal. Les frais seront remboursés, la liste des convives sera publiée et le ministère adoptera un menu plafonné à sa mesure.","effects":{"popularite":3,"assemblee":-3},"delayed":[{"delay":2,"effects":{"cohesion":2},"label":"Le restaurateur confirme avoir conservé toutes les notes"}],"news":"Le Premier ministre exige remboursement et liste des convives"},{"tone":"langue-de-bois","label":"Une enquête interne est en cours, et nous attendrons ses conclusions avant tout commentaire sur ce qui est, à ce stade, un dîner de travail.","effects":{"assemblee":2,"popularite":-3},"news":"Banquet : le gouvernement attend les conclusions « d’un dîner de travail »"},{"tone":"offensive","label":"Un repas ne devrait pas faire tomber un gouvernement. Que ceux qui n’ont jamais partagé un plat avec un collègue lancent la première baguette.","effects":{"assemblee":3,"popularite":-4,"international":-2},"news":"Le Premier ministre : « Que celui qui n’a jamais partagé un plat... »"}]},{"id":"japon-q-scandale-digues-entreprise","theme":"scandale","text":"L’entreprise qui construit les digues anti-tsunami appartient au cousin d’un conseiller du ministre concerné. L’archipel est-il protégé des vagues, ou des appels d’offres ?","answers":[{"tone":"franche","label":"Des deux, je l’espère. L’appel d’offres sera relancé sous contrôle indépendant, et le conseiller se tiendra à l’écart de tout dossier de digues.","effects":{"popularite":4,"economie":-3},"delayed":[{"delay":3,"effects":{"budget":2},"label":"Le nouvel appel d’offres est moins cher, de façon surprenante"}],"news":"Digues : le Premier ministre relance l’appel d’offres sous contrôle"},{"tone":"langue-de-bois","label":"Toutes les procédures de passation ont été respectées, et les liens familiaux n’ont, à ce jour, fait l’objet d’aucune observation de notre part.","effects":{"assemblee":2,"popularite":-3},"news":"Digues : le gouvernement n’a « aucune observation » sur les liens de famille"},{"tone":"offensive","label":"Dans un pays de cent vingt millions d’habitants, tout le monde est cousin de quelqu’un. Je ne punirai pas l’efficacité parce qu’elle a un arbre généalogique.","effects":{"economie":3,"popularite":-4,"cohesion":-3,"assemblee":2},"news":"Le Premier ministre : « Tout le monde est cousin de quelqu’un »"}]},{"id":"japon-q-scandale-cadeaux-fin-annee","theme":"scandale","text":"Des élus de la majorité auraient reçu, pour les fêtes, de somptueux paniers de cadeaux de la part d’entreprises qui plaident pour un texte. Les mandarines étaient-elles un argument ?","answers":[{"tone":"franche","label":"Peut-être, et c’est déjà trop. Tout cadeau supérieur à une boîte de thé sera déclaré, publié et, si besoin, restitué avec un mot aimable.","effects":{"popularite":4,"assemblee":-3},"delayed":[{"delay":2,"effects":{"cohesion":2},"label":"Les entreprises reprennent leurs paniers avec des mots d’excuse"}],"news":"Cadeaux de fêtes : plafond à une boîte de thé pour les élus"},{"tone":"langue-de-bois","label":"La tradition du don saisonnier est ancienne et respectable. Un cadre déontologique sera, le cas échéant, précisé après concertation avec les groupes.","effects":{"assemblee":2,"popularite":-3},"news":"Cadeaux : la tradition est « ancienne et respectable », dit-on"},{"tone":"offensive","label":"Qu’on arrête de chercher des scandales dans un panier de mandarines. L’opposition en reçoit aussi, et ses mandarines sont meilleures.","effects":{"assemblee":4,"popularite":-4,"cohesion":-2},"delayed":[{"delay":3,"effects":{"popularite":-2},"label":"Un décompte des paniers de l’opposition fait grincer des dents"}],"news":"Le Premier ministre : « Les mandarines de l’opposition sont meilleures »"}]},{"id":"japon-q-culture-sumo-baseball","theme":"popularite","text":"Votre agenda surchargé vous empêche d’assister aux tournois de sumo et aux matchs de base-ball. Dans ce pays, un chef de gouvernement peut-il vraiment gouverner sans avoir un club ?","answers":[{"tone":"franche","label":"J’avoue : je supporte l’équipe qui perd, par habitude. Je promets d’aller aux tribunes une fois par saison, sans caméras si possible.","effects":{"popularite":4,"economie":-2},"delayed":[{"delay":1,"effects":{"cohesion":2},"label":"Les supporters adoptent le Premier ministre comme porte-malheur officiel"}],"news":"Le Premier ministre avoue supporter l’équipe qui perd"},{"tone":"langue-de-bois","label":"Le sport est un puissant vecteur de cohésion. Je suis avec attention toutes les équipes, sans distinction de maillot ni de division.","effects":{"cohesion":2,"popularite":-2},"news":"Le Premier ministre suit « toutes les équipes sans distinction de maillot »"},{"tone":"offensive","label":"Mes adversaires lancent des balles hors du terrain ; moi, je lance le pays vers le haut. Prenez-moi pour un lanceur, pas un spectateur.","effects":{"popularite":5,"assemblee":-2,"international":-2},"news":"Le Premier ministre se compare à un lanceur de base-ball"}]},{"id":"japon-q-culture-sushi-diplomatie","theme":"international","text":"On dit qu’un dîner de sushis a plus fait pour vos relations internationales que trois sommets. Votre diplomatie se résume-t-elle à une assiette bien présentée ?","answers":[{"tone":"franche","label":"En partie. Un repas partagé ouvre des portes que des communiqués ne font que cogner. Mais je vérifie toujours l’addition avant de signer un accord.","effects":{"international":4,"budget":-2},"delayed":[{"delay":2,"effects":{"pouvoirAchat":-2},"label":"Le prix du poisson devient un sujet de conversation embarrassant"}],"news":"Diplomatie : le Premier ministre croit au pouvoir de l’assiette"},{"tone":"langue-de-bois","label":"La gastronomie fait partie de notre rayonnement culturel et contribue à la compréhension mutuelle entre nos peuples, dans un esprit d’amitié.","effects":{"international":2,"popularite":-2},"news":"Le Premier ministre vante le rôle de la gastronomie dans l’amitié"},{"tone":"offensive","label":"Si mon sushi convainc mieux que leurs discours, qu’ils méditent. Je suis prêt à servir le thé pendant les négociations, pourvu qu’ils paient l’addition.","effects":{"popularite":4,"international":-3,"assemblee":2},"news":"Le Premier ministre : « Je sers le thé, ils paient l’addition »"}]},{"id":"japon-q-culture-hanami","theme":"cohesion","text":"Chaque printemps, tout le pays étale des bâches sous les cerisiers pour un pique-nique parfois très arrosé. Un chef de gouvernement y a-t-il vraiment sa place, ou est-ce un congé déguisé ?","answers":[{"tone":"franche","label":"C’est un congé, mais un congé utile : on y écoute les gens mieux que dans un bureau. J’apporterai mon propre pique-nique, et ma propre bâche.","effects":{"cohesion":4,"economie":-2},"delayed":[{"delay":1,"effects":{"popularite":2},"label":"Une photo de lui sur une bâche rose devient virale"}],"news":"Le Premier ministre s’invite au pique-nique sous les cerisiers"},{"tone":"langue-de-bois","label":"La contemplation des fleurs est une tradition qui rassemble toutes les générations et nous rappelle la beauté de l’éphémère.","effects":{"cohesion":2,"popularite":-2},"news":"Le Premier ministre célèbre « la beauté de l’éphémère »"},{"tone":"offensive","label":"On m’accuse de pique-niquer ? Je travaille sous les fleurs, et mes dossiers y gagnent en poésie, ce qui n’est pas le cas de ceux de l’opposition.","effects":{"popularite":4,"assemblee":-3,"cohesion":-2},"news":"Le Premier ministre travaille « sous les fleurs » et défie l’opposition"}]},{"id":"japon-q-culture-courbette","theme":"international","text":"Lors du dernier sommet, votre salut a duré quelques secondes de plus que celui de votre homologue, et la presse débat de l’angle exact. Avez-vous perdu la bataille de la courbette ?","answers":[{"tone":"franche","label":"Je l’admets : j’ai salué trop longtemps, par politesse. Mais je préfère perdre quelques degrés de dignité que gagner un malentendu.","effects":{"international":4,"popularite":-2},"delayed":[{"delay":1,"effects":{"cohesion":2},"label":"Le pays s’attendrit devant ce salut un peu trop poli"}],"news":"Le Premier ministre admet avoir salué trop longtemps"},{"tone":"langue-de-bois","label":"Le salut est une marque de respect mutuel, et son angle exact importe moins que l’esprit de cordialité dans lequel il s’inscrit.","effects":{"international":2,"popularite":-2},"news":"Courbette : « l’angle importe moins que la cordialité »"},{"tone":"offensive","label":"La prochaine fois, je mesurerai l’angle avec un rapporteur et j’inviterai mon homologue à faire de même. Chacun son degré, mais personne ne sera plus bas.","effects":{"popularite":5,"international":-4,"assemblee":-2},"news":"Le Premier ministre sort le rapporteur pour mesurer sa courbette"}]},{"id":"japon-q-culture-empereur","theme":"cohesion","text":"L’empereur incarne l’unité du peuple sans gouverner, et vous gouvernez sans incarner grand-chose. Ne vous sentez-vous pas parfois comme le doublage de l’histoire ?","answers":[{"tone":"franche","label":"Si, et c’est très bien ainsi. Je décide, je rends des comptes et je dors moins ; lui rassemble, et la nation lui sait gré de dormir plus que moi.","effects":{"cohesion":4,"popularite":-2},"delayed":[{"delay":2,"effects":{"international":2},"label":"Des observateurs saluent cet équilibre des rôles"}],"news":"Le Premier ministre : « L’Empereur rassemble, moi je décide et je dors moins »"},{"tone":"langue-de-bois","label":"Les institutions de notre pays reposent sur un équilibre précieux, hérité de l’histoire, auquel chacun apporte sa contribution respectueuse.","effects":{"cohesion":2,"assemblee":-2},"news":"Institutions : le Premier ministre vante un « équilibre précieux »"},{"tone":"offensive","label":"Je suis la voix qui parle, il est le silence qui rassure. Je préfère ma part du travail, car on ne résout pas un budget en silence.","effects":{"popularite":4,"cohesion":-3,"assemblee":-2},"news":"Le Premier ministre : « On ne résout pas un budget en silence »"}]},{"id":"japon-q-culture-cool-biz","theme":"popularite","text":"Pour économiser la climatisation, vos ministres ont retiré cravate et veste, mais pas leur sérieux. Le style « tenue légère » rendra-t-il vos arbitrages plus frais ou seulement plus transpirants ?","answers":[{"tone":"franche","label":"Plus frais, j’en suis convaincu. Je donne l’exemple : manches courtes, thé glacé et pas de réunion de plus d’une heure en été.","effects":{"popularite":4,"ecologie":2,"assemblee":-2},"delayed":[{"delay":1,"effects":{"budget":2},"label":"Les factures d’électricité des ministères baissent d’un cran"}],"news":"Le Premier ministre : manches courtes, thé glacé, réunions courtes"},{"tone":"langue-de-bois","label":"La sobriété énergétique et le confort de travail sont compatibles. Une tenue adaptée à la saison contribue à une efficacité collective accrue.","effects":{"ecologie":2,"popularite":-2},"news":"Le Premier ministre promet « une efficacité collective accrue »"},{"tone":"offensive","label":"Une cravate ne fait pas un gouvernement, mais un ventilateur en panne en fait tomber. Je ferai installer des éventails à chaque banc de la Diète.","effects":{"popularite":4,"budget":-3,"assemblee":-2},"news":"Le Premier ministre veut des éventails sur chaque banc de la Diète"}]}]}'),u={pays:e,version:1,textes:s,institutions:t,election:n,lois:i,crises:a,missions:r,presse:o};export{a as crises,u as default,n as election,t as institutions,i as lois,r as missions,e as pays,o as presse,s as textes,l as version};
